def perfect(n):
    # Perfect numbers must be positive integers greater than 1.
    if n <= 1:
        return False

    sum_of_proper_divisors = 1  # Start with 1, as it's always a proper divisor for n > 1

    # Iterate from 2 up to the integer part of the square root of n
    limit = int(n**0.5) 
    for i in range(2, limit + 1):
        if n % i == 0:
            sum_of_proper_divisors += i
            # Add the corresponding divisor pair (n // i) if it's not the square root itself
            if i * i != n: 
                sum_of_proper_divisors += n // i

    # A number is perfect if the sum of its proper divisors equals the number itself.
    return sum_of_proper_divisors == n

